/* ---------------------------------------------------------------- helpers (the only data doors of the spec) */
const path = require('path');
const fs = require('fs');
const HTD_DIR = path.join(__dirname, '..', 'htd');
const _steps = new Map();
function unitRecord(slug) {
  const u = UNITS.find((x) => x.slug === slug);
  if (!u) throw new Error(`how-to-draw: "${slug}" is not a unit of the family`);
  return u;
}
/** the lesson of a unit: THROWS on a missing build, a refusal, or an inexact union (never a silent fallback) */
function stepsFor(slug) {
  if (_steps.has(slug)) return _steps.get(slug);
  unitRecord(slug);
  const f = path.join(HTD_DIR, slug + '.json');
  if (!fs.existsSync(f)) throw new Error(`how-to-draw: data/htd/${slug}.json is absent (node tools/htd-build.js --only=${slug})`);
  const S = JSON.parse(fs.readFileSync(f, 'utf8'));
  if (S.refused) throw new Error(`how-to-draw: ${slug} is REFUSED in data/htd/review.js: ${S.refused}`);
  if (!S.stats || S.stats.missing || S.stats.extra || S.stats.dup) throw new Error(`how-to-draw: ${slug} steps do not partition the drawing (missing ${S.stats && S.stats.missing}, extra ${S.stats && S.stats.extra})`);
  _steps.set(slug, S);
  return S;
}
function unitFor(block, mode) {
  const face = FACES[mode]; if (!face) throw new Error(`how-to-draw: unknown mode "${mode}"`);
  return (block && block.unitOverrides && block.unitOverrides[mode]) || face.unit;
}
function formFor(block, unit) { const f = block.forms && block.forms[unit]; if (!f || !f.t || !f.stem) throw new Error(`how-to-draw: no title form for ${unit} in this locale`); return f; }
function nounFor(block, unit) { const n = block.nouns && block.nouns[unit]; if (!n) throw new Error(`how-to-draw: no noun for ${unit} in this locale (nulled = the word face is refused here)`); return n; }
function startersFor(block, unit) { const s = block.starters && block.starters[unit]; if (!s || s.length !== 3) throw new Error(`how-to-draw: ${unit} needs exactly 3 starters in this locale`); return s; }

/** the K-379 scramble law for n cards: not the identity, not the reverse, forward chain ≤ 1, backward chain ≤ 1, fixed points ≤ 1 */
function lawN(perm) {
  const n = perm.length;
  const id = perm.every((v, i) => v === i + 1), rev = perm.every((v, i) => v === n - i);
  if (id || rev) return false;
  let fwd = 0, bwd = 0, fixed = 0;
  for (let i = 0; i < n; i++) { if (perm[i] === i + 1) fixed++; if (i + 1 < n && perm[i + 1] === perm[i] + 1) fwd++; if (i + 1 < n && perm[i + 1] === perm[i] - 1) bwd++; }
  return fwd <= 1 && bwd <= 1 && fixed <= 1;
}
/** a weighted draw from SCRAMBLE5 / SCRAMBLE4 → an array of step numbers (slot order) */
function drawScramble(table, rng) {
  const keys = Object.keys(table), total = keys.reduce((a, k) => a + table[k], 0);
  let r = rng.next() * total;
  for (const k of keys) { r -= table[k]; if (r <= 0) return String(k).split('').map(Number); }
  return String(keys[keys.length - 1]).split('').map(Number);
}

/** validator rules 1-16 of K-396 final §5 that are checkable on a locale block + the engine data (tools/validate-b7-draft.js) */
function validateBank(block, loc) {
  const errs = [];
  const UNIT = new Set(UNITS.map((u) => u.slug));
  for (const mode of MODES) {
    const face = FACES[mode];
    const unit = unitFor(block, mode);
    if (!UNIT.has(unit)) { errs.push(`${mode}: unit "${unit}" is not in units[]`); continue; }
    let S; try { S = stepsFor(unit); } catch (e) { errs.push(`${mode}: ${e.message}`); continue; }
    const n = S.steps.length;
    if (n < COMMON.STEPS_RANGE[0] || n > COMMON.STEPS_RANGE[1]) errs.push(`${mode}: ${unit} has ${n} steps (4–5)`);
    if (S.steps[0].kind !== 'outline' || S.steps[0].share < COMMON.OUTLINE_MIN) errs.push(`${mode}: ${unit} step 1 is not an outline ≥ 0.25`);
    S.steps.slice(1).forEach((s, i) => { if (s.share < COMMON.STEP_FLOOR) errs.push(`${mode}: ${unit} step ${i + 2} share ${s.share} < ${COMMON.STEP_FLOOR}`); });
    const ds = new Set(S.steps.map((s) => s.d)); if (ds.size !== n || S.steps.some((s) => !s.d)) errs.push(`${mode}: ${unit} has a repeated or empty step path`);
    if (face.band === 'K' && face.needsSteps && n !== COMMON.K_STEPS) errs.push(`${mode}: a K face needs exactly ${COMMON.K_STEPS} steps, ${unit} has ${n}`);
    if (face.minSteps && n < face.minSteps) errs.push(`${mode}: ${unit} has ${n} < ${face.minSteps} steps`);
    if (face.needsShapes) {
      const bb = S.bbox, area = (bb[2] - bb[0]) * (bb[3] - bb[1]);
      const best = (S.shapes || []).filter((x) => x.kind).sort((a, b) => b.area - a.area)[0];
      if (!best || best.coverage < COMMON.SHAPE_FLOOR.coverage || best.area < COMMON.SHAPE_FLOOR.areaShare * area) errs.push(`${mode}: ${unit} has no shape guide with coverage ≥ 0.75 and area ≥ 15 % of the bbox`);
    }
    if (face.needsScene) {
      const u = unitRecord(unit);
      const f = path.join(__dirname, '..', 'fd', (u.fdScene || '') + '.json');
      if (!u.fdScene || !fs.existsSync(f)) errs.push(`${mode}: ${unit} has no fd scene`);
      else { const sc = JSON.parse(fs.readFileSync(f, 'utf8')); const hero = sc.items[u.heroItem]; if (!hero || !hero.src.toLowerCase().replace(/[^a-z0-9]+/g, '-').includes(unit.replace(/-\d+$/, '').slice(0, 12))) errs.push(`${mode}: fd scene item ${u.heroItem} is not the unit`); if (sc.items.length - 1 < 2) errs.push(`${mode}: fewer than 2 non-hero items remain`); }
    }
    if (face.needsNoun && !(block.refusals && block.refusals[mode])) {
      const noun = block.nouns && block.nouns[unit];
      if (!noun) errs.push(`${mode}: no noun for ${unit} (null it AND refuse the face, or author it)`);
      else {
        if (/\s/.test(noun) || [...noun].length > 12) errs.push(`${mode}: noun "${noun}" has a space or > 12 glyphs`);
        if (/^(der|die|das|ein|eine|el|la|un|una|o|a|um|uma|le|les|une|il|lo|de|het|een|en|ett|et)\s/i.test(noun)) errs.push(`${mode}: noun "${noun}" starts with an article`);
      }
    }
    if (face.needsStarters) { const st = block.starters && block.starters[unit]; if (!st || st.length !== 3 || new Set(st).size !== 3) errs.push(`${mode}: ${unit} needs 3 distinct starters`); else st.forEach((s) => { if ([...s].length > 22 || /[.?!]$/.test(s) || /\{/.test(s)) errs.push(`${mode}: starter "${s}" > 22 chars, ends in a mark, or holds a slot`); }); }
    const f = block.forms && block.forms[unit];
    if (!f || !f.t || !f.stem) errs.push(`${mode}: forms[${unit}] needs t + stem`);
    else if (!new RegExp('(?<!\\p{L})' + f.stem.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'iu').test(f.t.normalize('NFC'))) errs.push(`${mode}: stem "${f.stem}" is not in the title form "${f.t}"`);
    if (f && f.n != null && (typeof f.n !== 'string' || !f.n.trim() || /^(der|die|das|ein|eine|el|la|un|una|o|a|um|uma|le|les|une|il|lo|de|het|een|en|ett|et|an|the)\s/i.test(f.n))) errs.push(`${mode}: forms[${unit}].n must be the bare noun without an article`);
    const s = block.strings && block.strings[mode];
    if (!s || !s.title || !s.instruction) { errs.push(`${mode}: strings.${mode} needs title + instruction`); continue; }
    const toks = (s.title.match(/\{(U|L|N)\}/g) || []).length;
    if (toks !== 1 || /\{(?!U\}|L\}|N\})/.test(s.title)) errs.push(`${mode}: the title needs exactly one {U}, {L} or {N} and no other token`);
    if (/\{N\}/.test(s.title) && !(f && f.n)) errs.push(`${mode}: the title uses {N} but forms[${unit}] has no n`);
    const resolved = s.title.replace(/\{[ULN]\}/, (m) => (f ? (m === '{N}' ? f.n : f.t) : '?'));
    if ([...resolved].length > 70) errs.push(`${mode}: title "${resolved}" > 70 chars`);
    if (/\b(story|stories|tracing|nachspuren|malen|gitterbild|stitch|pokemon|minecraft|peppa|worksheet|arbeitsblatt|ficha|fiche|scheda|werkblad|arbetsblad|tehtävä)\b/i.test(resolved)) errs.push(`${mode}: title "${resolved}" carries a forbidden head word`);
    if ([...s.instruction].length > 150) errs.push(`${mode}: instruction > 150 chars`);
    if (f && f.stem && !new RegExp(f.stem.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'iu').test(s.instruction.normalize('NFC'))) errs.push(`${mode}: the instruction does not name the unit (stem "${f.stem}")`);
    if (/answer key|lösung|solución|gabarito|corrigé|soluzione|antwoord|facit|fasit|vastaukset|online|interactive/i.test(s.title + ' ' + s.instruction)) errs.push(`${mode}: a string promises a key or a screen`);
    if (mode === 'memory' && (!s.foldWord || !s.instruction.toLowerCase().includes(String(s.foldWord).toLowerCase()))) errs.push('memory: the instruction must contain foldWord');
    if (mode === 'order' && !/[15]/.test(s.instruction)) errs.push('order: the instruction must name the numbers 1 and 5');
  }
  const sk = Object.keys((block.strings) || {}).sort().join(','), mk = MODES.slice().sort().join(',');
  if (sk !== mk) errs.push(`strings keys must be exactly the 11 modes (got ${sk})`);
  for (const [k, v] of Object.entries(block.refusals || {})) if (!v || v.length < 12) errs.push(`refusals.${k}: a reason ≥ 12 chars`);
  for (const [k, v] of Object.entries(block.unitOverrides || {})) if (!FACES[k] || !UNIT.has(v)) errs.push(`unitOverrides.${k} = ${v} is not a face → unit`);
  // SCRAMBLE5: law5 keys, weights sum to 1, every (step, slot) marginal 0.200
  const T = COMMON.SCRAMBLE5, keys = Object.keys(T), sum = keys.reduce((a, k) => a + T[k], 0);
  if (Math.abs(sum - 1) > 0.001) errs.push(`SCRAMBLE5 weights sum to ${sum.toFixed(3)}`);
  for (const k of keys) if (!lawN(String(k).split('').map(Number))) errs.push(`SCRAMBLE5 key ${k} breaks law5`);
  for (let slot = 0; slot < 5; slot++) for (let step = 1; step <= 5; step++) { const m = keys.reduce((a, k) => a + (String(k)[slot] === String(step) ? T[k] : 0), 0); if (Math.abs(m - 0.2) > 0.005) errs.push(`SCRAMBLE5 step ${step} slot ${slot + 1} marginal ${m.toFixed(3)}`); }
  void loc;
  return errs;
}

module.exports = { HOW_TO_DRAW, COMMON, UNITS, FACES, MODES, stepsFor, unitFor, unitRecord, formFor, nounFor, startersFor, lawN, drawScramble, validateBank };
